import{_ as a,o as i,c as e,ae as s}from"./chunks/framework.DICTGE3h.js";const t="/blog/assets/skill%E5%B7%A5%E4%BD%9C%E6%B5%81%E7%A8%8B.BsD9JQuH.png",u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"note/ai/agent/output/AI Skill 是什么.md","filePath":"note/ai/agent/output/AI Skill 是什么.md"}'),p={name:"note/ai/agent/output/AI Skill 是什么.md"};function n(o,l,d,r,c,h){return i(),e("div",null,[...l[0]||(l[0]=[s(`<h2 id="先说结论" tabindex="-1">先说结论 <a class="header-anchor" href="#先说结论" aria-label="Permalink to &quot;先说结论&quot;">​</a></h2><p><code>Skill</code> 可以先理解成 AI 的“专业能力模块”。</p><p>它不是一段临时 prompt，也不是一个外部工具。更准确地说，Skill 是把一类任务里的经验、规则、操作流程和参考资料，封装成一份可复用的说明书。</p><p>比如：</p><ul><li>写周报时，加载“周报整理 Skill”。</li><li>审阅合同时，加载“合同审阅 Skill”。</li><li>清洗数据时，加载“数据清洗 Skill”。</li><li>整理会议录音时，加载“会议纪要 Skill”。</li></ul><p>好的 Skill 不能把弱模型变成强模型，但能减少模型在具体任务里的摇摆。</p><p>这里的“强模型”和“弱模型”不是永久标签，而是相对任务复杂度来说的。</p><p>强模型通常指各家公司旗舰级、推理型或专业工作模型。比如 GPT、Claude、Gemini、DeepSeek、Qwen 这些模型家族里的高端版本，通常更适合处理长上下文、多步骤推理、复杂代码、严肃分析和 Agent 工作流。</p><p>弱模型不是贬义，更多是指能力、上下文、推理深度或稳定性更有限的模型。比如旧一代模型、小参数本地模型、量化后的 7B/8B/14B 模型，或者各家为了低成本和低延迟设计的 <code>mini</code>、<code>lite</code>、<code>flash-lite</code> 类模型。它们很适合分类、改写、简单摘要、格式转换这类边界清楚的任务。但遇到复杂规划、长文档推理或多工具协作时，更容易漏步骤、误解约束，或者前后说法不一致。</p><p>Skill 的作用，是把任务流程、质量标准和反例提前写清楚。强模型用了 Skill，输出会更稳；弱模型用了 Skill，也能少犯一些低级错误。但如果任务本身需要很强的推理、长上下文或专业判断，Skill 不能替代模型能力。</p><h2 id="为什么需要-skill" tabindex="-1">为什么需要 Skill？ <a class="header-anchor" href="#为什么需要-skill" aria-label="Permalink to &quot;为什么需要 Skill？&quot;">​</a></h2><p>很多人刚开始用 AI，习惯把所有要求都塞进一段长 prompt：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你是一个资深编辑，请帮我写文章。</span></span>
<span class="line"><span>要求语言自然，结构清晰，不要 AI 味，适合对外发布。</span></span>
<span class="line"><span>标题要吸引人，内容要有案例，还要有结论。</span></span></code></pre></div><p>这类 prompt 当然能用，但问题也明显：</p><ul><li>每次都要重新写。</li><li>规则散落在聊天记录里，不好维护。</li><li>复杂任务会越写越长，最后重点被淹没。</li><li>同类任务之间无法沉淀经验。</li><li>换一个 AI 工具后，又要重新组织一遍。</li></ul><p>Skill 解决的就是“经验复用”的问题。</p><p>它把那些稳定、反复出现、值得沉淀的做法写成文件。AI 在需要时读取这个文件，再按里面的流程执行任务。</p><p>你可以把 Skill 理解成三件东西的结合：</p><ul><li>AI 的专业知识模块。</li><li>AI 的长期记忆和行为约束。</li><li>某个任务或技术栈的官方用法说明书。</li></ul><h2 id="skill-如何触发" tabindex="-1">Skill 如何触发？ <a class="header-anchor" href="#skill-如何触发" aria-label="Permalink to &quot;Skill 如何触发？&quot;">​</a></h2><p>Skill 的触发通常有两种方式：用户显式触发，以及系统自动触发。</p><h3 id="用户显式触发" tabindex="-1">用户显式触发 <a class="header-anchor" href="#用户显式触发" aria-label="Permalink to &quot;用户显式触发&quot;">​</a></h3><p>最直接的方式，是你在请求里点名某个 Skill。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>使用 weekly-report skill，帮我把这些工作记录整理成本周周报。</span></span></code></pre></div><p>这种方式最稳定，因为你已经明确告诉 AI：这次任务应该使用哪个能力模块。</p><h3 id="系统自动触发" tabindex="-1">系统自动触发 <a class="header-anchor" href="#系统自动触发" aria-label="Permalink to &quot;系统自动触发&quot;">​</a></h3><p>更常见的方式，是 AI 根据 Skill 的元信息判断是否需要加载。</p><p>每个 <code>SKILL.md</code> 文件开头一般都有一段 YAML FrontMatter：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">---</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">weekly-report</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;整理和生成工作周报。适用于周报、本周总结、weekly report、项目进展汇总。当用户要求整理一周工作、生成周报或总结项目进展时使用。&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">---</span></span></code></pre></div><p>其中最关键的是：</p><ul><li><code>name</code>：Skill 的名称。</li><li><code>description</code>：说明这个 Skill 能干什么、什么时候应该使用。</li></ul><p>当用户说“帮我写周报”“整理本周工作”“把这些记录变成本周总结”时，AI 会根据 description 判断：这可能匹配 <code>weekly-report</code>，于是读取对应的 <code>SKILL.md</code>。</p><p>所以，Skill 能不能被准确触发，很大程度取决于 <code>description</code> 写得清不清楚。</p><h2 id="skill-如何工作" tabindex="-1">Skill 如何工作？ <a class="header-anchor" href="#skill-如何工作" aria-label="Permalink to &quot;Skill 如何工作？&quot;">​</a></h2><p>Skill 的工作方式，可以概括成一句话：</p><p>AI 先看 Skill 的元信息，判断是否相关；相关时再读取正文和必要资源，把这些内容临时加入当前任务上下文。</p><p>一个简化流程如下：</p><p><img src="`+t+`" alt="Mermaid 图 1"></p><p>这里有一个关键点：Skill 应该渐进式加载。</p><p>也就是说，AI 不应该一上来把 Skill 目录里的所有内容都读完。更合理的做法是：</p><ol><li>先看 Skill 的头部元信息，判断是否该用。</li><li>再读 <code>SKILL.md</code> 的总流程。</li><li>如果流程需要，再读取具体的参考资料、模板、脚本或资产。</li></ol><p>这样能减少上下文浪费。AI 的上下文窗口不是无限的。如果一个 Skill 把规则、案例、模板、FAQ 全塞进一个大文件，模型每次都要加载一大坨内容，任务重点反而会被淹没。</p><h2 id="一个-skill-通常长什么样" tabindex="-1">一个 Skill 通常长什么样？ <a class="header-anchor" href="#一个-skill-通常长什么样" aria-label="Permalink to &quot;一个 Skill 通常长什么样？&quot;">​</a></h2><p>一个基础 Skill 可以只有一个文件：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>weekly-report/</span></span>
<span class="line"><span>└── SKILL.md</span></span></code></pre></div><p>复杂一点的 Skill，可以带上辅助资源：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>weekly-report/</span></span>
<span class="line"><span>├── SKILL.md</span></span>
<span class="line"><span>├── references/</span></span>
<span class="line"><span>│   └── report-style.md</span></span>
<span class="line"><span>├── scripts/</span></span>
<span class="line"><span>│   └── summarize_tasks.py</span></span>
<span class="line"><span>└── assets/</span></span>
<span class="line"><span>    └── weekly-template.md</span></span></code></pre></div><p>其中 <code>SKILL.md</code> 是核心。</p><p>它一般由两部分组成：</p><ul><li>FrontMatter：告诉 AI 这个 Skill 叫什么、什么时候使用。</li><li>Markdown 正文：告诉 AI 触发后具体怎么做。</li></ul><p>正文至少要回答几个问题：</p><ul><li>这个 Skill 的目标是什么？</li><li>执行步骤是什么？</li><li>输出格式是什么？</li><li>有哪些质量标准？</li><li>遇到模糊需求时应该怎么问？</li><li>有哪些常见错误要避免？</li></ul><h2 id="skill、system-prompt-和-mcp-的区别" tabindex="-1">Skill、System Prompt 和 MCP 的区别 <a class="header-anchor" href="#skill、system-prompt-和-mcp-的区别" aria-label="Permalink to &quot;Skill、System Prompt 和 MCP 的区别&quot;">​</a></h2><p>这三者经常被混在一起，但分工完全不同。</p><table tabindex="0"><thead><tr><th>名称</th><th>解决什么问题</th><th>什么时候加载</th><th>典型内容</th></tr></thead><tbody><tr><td>System Prompt</td><td>全局行为规则</td><td>每轮对话都加载</td><td>身份、语气、安全边界、通用约束</td></tr><tr><td>Skill</td><td>某类任务的知识和流程</td><td>命中任务时加载</td><td>执行步骤、质量标准、模板、示例</td></tr><tr><td>MCP</td><td>外部能力接口</td><td>需要调用工具时使用</td><td>数据库、浏览器、文件系统、第三方 API</td></tr></tbody></table><p>一句话区分：</p><ul><li>System Prompt 告诉 AI “你始终应该怎么做”。</li><li>Skill 告诉 AI “遇到这类任务时应该怎么做”。</li><li>MCP 告诉 AI “你可以调用哪些外部能力去做”。</li></ul><p>比如用户说：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我把这篇文章做成一份 PPT。</span></span></code></pre></div><p>可能发生的是：</p><ol><li>System Prompt 约束 AI 的总体行为，比如要直接、准确、不要编造。</li><li>PowerPoint Skill 告诉 AI 如何设计页面结构、版式、图表和演示节奏。</li><li>文件系统或文档工具作为 MCP/工具接口，让 AI 真正创建 <code>.pptx</code> 文件。</li></ol><p>三者不是替代关系，而是搭配关系。</p><h2 id="什么样的-skill-才算好" tabindex="-1">什么样的 Skill 才算好？ <a class="header-anchor" href="#什么样的-skill-才算好" aria-label="Permalink to &quot;什么样的 Skill 才算好？&quot;">​</a></h2><p>我会用五个标准判断一个 Skill 好不好。</p><h3 id="_1-触发准确" tabindex="-1">1. 触发准确 <a class="header-anchor" href="#_1-触发准确" aria-label="Permalink to &quot;1. 触发准确&quot;">​</a></h3><p>用户提出相关任务时，它能被加载；用户提出无关任务时，它不会乱入。</p><p>这主要靠 <code>name</code> 和 <code>description</code>。</p><h3 id="_2-边界清楚" tabindex="-1">2. 边界清楚 <a class="header-anchor" href="#_2-边界清楚" aria-label="Permalink to &quot;2. 边界清楚&quot;">​</a></h3><p>它应该说清楚适合什么任务、不适合什么任务，以及和相邻 Skill 的区别是什么。</p><h3 id="_3-流程可执行" tabindex="-1">3. 流程可执行 <a class="header-anchor" href="#_3-流程可执行" aria-label="Permalink to &quot;3. 流程可执行&quot;">​</a></h3><p>正文不能只有“专业、自然、高质量”这类价值观。AI 读完以后，应该知道先做什么、后做什么，遇到缺信息时怎么处理，最后输出什么格式。</p><h3 id="_4-内容可渐进加载" tabindex="-1">4. 内容可渐进加载 <a class="header-anchor" href="#_4-内容可渐进加载" aria-label="Permalink to &quot;4. 内容可渐进加载&quot;">​</a></h3><p>不要把所有材料塞进一个超长 <code>SKILL.md</code>。核心流程放正文，长资料拆成 <code>references/</code>，固定素材放进 <code>assets/</code>，稳定脚本放进 <code>scripts/</code>。</p><h3 id="_5-能持续迭代" tabindex="-1">5. 能持续迭代 <a class="header-anchor" href="#_5-能持续迭代" aria-label="Permalink to &quot;5. 能持续迭代&quot;">​</a></h3><p>Skill 不是一次性写完的。每次你发现 AI 输出不稳定，都可以回到 Skill 里补一条规则、一个反例、一个模板，或者一个脚本。</p><h2 id="什么时候应该使用-skill" tabindex="-1">什么时候应该使用 Skill？ <a class="header-anchor" href="#什么时候应该使用-skill" aria-label="Permalink to &quot;什么时候应该使用 Skill？&quot;">​</a></h2><p>如果一个任务只做一次，不一定要写 Skill。</p><p>但如果你发现自己反复对 AI 说同样的话，就可以考虑沉淀成 Skill。</p><p>典型信号包括：</p><ul><li>你经常复制同一段 prompt。</li><li>你经常纠正 AI 的同一种错误。</li><li>你希望某类输出保持固定格式。</li><li>你有一套自己的审美、流程或判断标准。</li><li>你希望换工具后仍能复用这套经验。</li></ul><p>比如写文章这件事，如果你每次都要提醒它：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>不要写得太像 AI。</span></span>
<span class="line"><span>开头别废话。</span></span>
<span class="line"><span>先给结论。</span></span>
<span class="line"><span>每段短一点。</span></span>
<span class="line"><span>保留关键判断。</span></span>
<span class="line"><span>不要乱用形容词。</span></span></code></pre></div><p>那就可以做一个写作 Skill。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>Skill 的本质不是“更长的提示词”，而是“可复用的任务工作流”。</p><p>它把经验从聊天窗口里抽出来，变成可以命名、触发、维护和组合的文件。这样 AI 在处理重复任务时，不需要每次从零理解你的偏好，也不用临场猜什么叫“专业”。</p><p>真正有价值的 Skill，通常不是写得最长的那个，而是边界最清楚、触发最准确、流程最可执行的那个。</p>`,87)])])}const m=a(p,[["render",n]]);export{u as __pageData,m as default};
